{
  "name": "CRM Pro - Lead & Customer Management",
  "description": "A React-based CRM prototype featuring lead assignment, employee tracking, and resignation resource recycling logic."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum Role {
  SUPER_ADMIN = 'SUPER_ADMIN',
  ADMIN = 'ADMIN',
  EMPLOYEE = 'EMPLOYEE',
}

export enum EmployeeStatus {
  ACTIVE = 'ACTIVE',
  INACTIVE = 'INACTIVE',
}

export interface Employee {
  id: string;
  name: string;
  role: Role;
  status: EmployeeStatus;
  email: string;
  leftAt?: string; // ISO Date string
  assignedLeadsCount?: number; // Mock aggregate
  customerCount?: number; // Mock aggregate
}

export enum LeadStatus {
  UNASSIGNED = 'UNASSIGNED', // In pool
  ASSIGNED = 'ASSIGNED',     // Assigned to emp
  FOLLOWING = 'FOLLOWING',   // Being worked on
  DEAL = 'DEAL',             // Converted
  INVALID = 'INVALID',       // Trash
}

export enum RecycleReason {
  EMPLOYEE_LEFT = 'EMPLOYEE_LEFT',
  MANUAL = 'MANUAL',
}

export interface Lead {
  id: string;
  name: string;
  phone: string;
  source: string;
  batchId: string;
  status: LeadStatus;
  ownerId?: string; // undefined if UNASSIGNED
  createdAt: string;
  updatedAt: string;
  recycledAt?: string;
  recycleReason?: RecycleReason;
  notes?: string;
}

export interface FollowUp {
  id: string;
  leadId: string;
  ownerId: string;
  content: string;
  createdAt: string;
  nextFollowUpAt?: string;
}

export interface Customer {
  id: string;
  leadId: string;
  name: string;
  phone: string;
  ownerId?: string;
  dealAt: string;
  updatedAt: string;
  tags: string[];
  recycledAt?: string;
}

// For UI state
export interface UserSession {
  id: string;
  name: string;
  role: Role;
}

import { 
  Employee, 
  Lead, 
  FollowUp, 
  Customer, 
  Role, 
  EmployeeStatus, 
  LeadStatus, 
  RecycleReason 
} from '../types';

// --- Initial Data ---

const MOCK_EMPLOYEES: Employee[] = [
  { id: 'emp_001', name: 'Alice Super', email: 'alice@crm.com', role: Role.SUPER_ADMIN, status: EmployeeStatus.ACTIVE },
  { id: 'emp_002', name: 'Bob Admin', email: 'bob@crm.com', role: Role.ADMIN, status: EmployeeStatus.ACTIVE },
  { id: 'emp_003', name: 'Charlie Sales', email: 'charlie@crm.com', role: Role.EMPLOYEE, status: EmployeeStatus.ACTIVE },
  { id: 'emp_004', name: 'David Sales', email: 'david@crm.com', role: Role.EMPLOYEE, status: EmployeeStatus.ACTIVE },
  { id: 'emp_005', name: 'Eve Quitter', email: 'eve@crm.com', role: Role.EMPLOYEE, status: EmployeeStatus.INACTIVE, leftAt: '2023-10-01T10:00:00Z' },
];

const MOCK_LEADS: Lead[] = [
  { id: 'lead_101', name: 'John Doe', phone: '13800138000', source: 'Web', batchId: 'B001', status: LeadStatus.UNASSIGNED, createdAt: '2023-10-25T09:00:00Z', updatedAt: '2023-10-25T09:00:00Z' },
  { id: 'lead_102', name: 'Jane Smith', phone: '13900139000', source: 'Referral', batchId: 'B001', status: LeadStatus.ASSIGNED, ownerId: 'emp_003', createdAt: '2023-10-26T10:00:00Z', updatedAt: '2023-10-26T11:00:00Z' },
  { id: 'lead_103', name: 'Mike Johnson', phone: '13700137000', source: 'Ad', batchId: 'B002', status: LeadStatus.FOLLOWING, ownerId: 'emp_003', createdAt: '2023-10-27T14:00:00Z', updatedAt: '2023-10-27T15:30:00Z' },
  { id: 'lead_104', name: 'Sarah Connor', phone: '15000150000', source: 'Web', batchId: 'B002', status: LeadStatus.UNASSIGNED, createdAt: '2023-10-28T09:00:00Z', updatedAt: '2023-10-28T09:00:00Z' },
  { id: 'lead_105', name: 'T-800', phone: '19900199000', source: 'Future', batchId: 'B003', status: LeadStatus.ASSIGNED, ownerId: 'emp_004', createdAt: '2023-10-28T16:00:00Z', updatedAt: '2023-10-28T16:00:00Z' },
];

const MOCK_FOLLOWUPS: FollowUp[] = [
  { id: 'fu_01', leadId: 'lead_103', ownerId: 'emp_003', content: 'Called, no answer. Left voicemail.', createdAt: '2023-10-27T15:30:00Z' }
];

const MOCK_CUSTOMERS: Customer[] = [];

// --- In-Memory Store ---

let employees = [...MOCK_EMPLOYEES];
let leads = [...MOCK_LEADS];
let followUps = [...MOCK_FOLLOWUPS];
let customers = [...MOCK_CUSTOMERS];

// --- Helpers ---

const delay = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));
const randomDelay = () => delay(Math.floor(Math.random() * 500) + 300);

// --- API Methods ---

// 1. Employee Management
export const mockListEmployees = async (): Promise<Employee[]> => {
  await randomDelay();
  // Calculate aggregates dynamically for the UI
  return employees.map(emp => ({
    ...emp,
    assignedLeadsCount: leads.filter(l => l.ownerId === emp.id && l.status !== LeadStatus.DEAL && l.status !== LeadStatus.INVALID).length,
    customerCount: customers.filter(c => c.ownerId === emp.id).length
  }));
};

export const mockActivateEmployee = async (employeeId: string): Promise<void> => {
  await randomDelay();
  employees = employees.map(e => e.id === employeeId ? { ...e, status: EmployeeStatus.ACTIVE, leftAt: undefined } : e);
};

export const mockDeactivateEmployee = async (employeeId: string): Promise<{ recycledLeadCount: number }> => {
  await randomDelay();
  const now = new Date().toISOString();
  let recycledCount = 0;

  // 1. Deactivate Employee
  employees = employees.map(e => e.id === employeeId ? { ...e, status: EmployeeStatus.INACTIVE, leftAt: now } : e);

  // 2. Recycle Leads
  leads = leads.map(lead => {
    if (lead.ownerId === employeeId && lead.status !== LeadStatus.DEAL && lead.status !== LeadStatus.INVALID) {
      recycledCount++;
      return {
        ...lead,
        ownerId: undefined,
        status: LeadStatus.UNASSIGNED,
        recycledAt: now,
        recycleReason: RecycleReason.EMPLOYEE_LEFT,
        updatedAt: now,
      };
    }
    return lead;
  });

  // 3. (Optional) Recycle Customers or just mark them
  // For this requirement, we focus on Leads returning to pool.

  return { recycledLeadCount: recycledCount };
};

// 2. Lead Management
export const mockListLeads = async (filters?: { ownerId?: string; status?: LeadStatus }): Promise<Lead[]> => {
  await randomDelay();
  let result = [...leads];
  if (filters?.ownerId) {
    result = result.filter(l => l.ownerId === filters.ownerId);
  }
  if (filters?.status) {
    result = result.filter(l => l.status === filters.status);
  }
  // Sort by updatedAt desc
  return result.sort((a, b) => new Date(b.updatedAt).getTime() - new Date(a.updatedAt).getTime());
};

export const mockImportLeads = async (newLeadsData: Partial<Lead>[]): Promise<void> => {
  await randomDelay();
  const now = new Date().toISOString();
  const newLeads = newLeadsData.map((d, i) => ({
    ...d,
    id: `lead_new_${Date.now()}_${i}`,
    status: LeadStatus.UNASSIGNED,
    createdAt: now,
    updatedAt: now,
  } as Lead));
  leads = [...leads, ...newLeads];
};

export const mockAssignLeadsToEmployee = async (leadIds: string[], employeeId: string): Promise<void> => {
  await randomDelay();
  const now = new Date().toISOString();
  leads = leads.map(l => {
    if (leadIds.includes(l.id)) {
      return {
        ...l,
        ownerId: employeeId,
        status: LeadStatus.ASSIGNED,
        updatedAt: now,
        recycleReason: undefined, // Clear recycle reason on reassignment
        recycledAt: undefined
      };
    }
    return l;
  });
};

export const mockAutoAssignLeads = async (): Promise<{ assignedCount: number }> => {
  await randomDelay();
  const activeEmployees = employees.filter(e => e.status === EmployeeStatus.ACTIVE && e.role === Role.EMPLOYEE);
  const unassignedLeads = leads.filter(l => l.status === LeadStatus.UNASSIGNED);

  if (activeEmployees.length === 0 || unassignedLeads.length === 0) {
    return { assignedCount: 0 };
  }

  const now = new Date().toISOString();
  let assignedCount = 0;

  unassignedLeads.forEach((lead, index) => {
    const targetEmp = activeEmployees[index % activeEmployees.length];
    // Update the lead in the main array
    const leadIndex = leads.findIndex(l => l.id === lead.id);
    if (leadIndex !== -1) {
      leads[leadIndex] = {
        ...leads[leadIndex],
        ownerId: targetEmp.id,
        status: LeadStatus.ASSIGNED,
        updatedAt: now,
        recycleReason: undefined,
        recycledAt: undefined
      };
      assignedCount++;
    }
  });

  return { assignedCount };
};

export const mockUpdateLeadStatus = async (leadId: string, status: LeadStatus, dealData?: {name: string}): Promise<void> => {
  await randomDelay();
  const now = new Date().toISOString();
  const lead = leads.find(l => l.id === leadId);

  if (!lead) throw new Error("Lead not found");

  leads = leads.map(l => l.id === leadId ? { ...l, status, updatedAt: now } : l);

  // If DEAL, create Customer
  if (status === LeadStatus.DEAL && dealData) {
    customers.push({
      id: `cust_${Date.now()}`,
      leadId: lead.id,
      name: dealData.name || lead.name,
      phone: lead.phone,
      ownerId: lead.ownerId,
      dealAt: now,
      updatedAt: now,
      tags: [],
    });
  }
};

// 3. Follow Ups
export const mockGetFollowUps = async (leadId: string): Promise<FollowUp[]> => {
  await randomDelay();
  return followUps.filter(f => f.leadId === leadId).sort((a,b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());
};

export const mockAddFollowUp = async (leadId: string, ownerId: string, content: string): Promise<FollowUp> => {
  await randomDelay();
  const newFu: FollowUp = {
    id: `fu_${Date.now()}`,
    leadId,
    ownerId,
    content,
    createdAt: new Date().toISOString()
  };
  followUps = [newFu, ...followUps];

  // Also update lead updated_at
  leads = leads.map(l => l.id === leadId ? { ...l, updatedAt: new Date().toISOString() } : l);

  return newFu;
};

import React from 'react';
import { UserSession, Role } from '../types';
import { 
  Users, 
  Phone, 
  LayoutDashboard, 
  LogOut, 
  Briefcase
} from 'lucide-react';

interface SidebarProps {
  user: UserSession;
  currentPage: string;
  onNavigate: (page: string) => void;
  onLogout: () => void;
}

export const Sidebar: React.FC<SidebarProps> = ({ user, currentPage, onNavigate, onLogout }) => {
  const isSuperAdmin = user.role === Role.SUPER_ADMIN;
  const isAdminOrSuper = user.role === Role.ADMIN || isSuperAdmin;

  const NavItem = ({ page, icon: Icon, label }: { page: string; icon: any; label: string }) => (
    <button
      onClick={() => onNavigate(page)}
      className={`flex items-center w-full px-4 py-3 text-sm font-medium transition-colors ${
        currentPage === page
          ? 'bg-blue-50 text-blue-700 border-r-4 border-blue-700'
          : 'text-gray-600 hover:bg-gray-50 hover:text-gray-900'
      }`}
    >
      <Icon className="w-5 h-5 mr-3" />
      {label}
    </button>
  );

  return (
    <div className="w-64 bg-white border-r border-gray-200 flex flex-col h-screen fixed left-0 top-0">
      <div className="p-6 border-b border-gray-100">
        <h1 className="text-xl font-bold text-blue-600 flex items-center gap-2">
          <Phone className="fill-current" /> CRM Pro
        </h1>
        <div className="mt-4 p-3 bg-gray-50 rounded-lg">
          <p className="text-sm font-semibold text-gray-900">{user.name}</p>
          <span className={`text-xs px-2 py-0.5 rounded-full mt-1 inline-block ${
            isSuperAdmin ? 'bg-purple-100 text-purple-700' :
            user.role === Role.ADMIN ? 'bg-indigo-100 text-indigo-700' :
            'bg-green-100 text-green-700'
          }`}>
            {user.role.replace('_', ' ')}
          </span>
        </div>
      </div>

      <nav className="flex-1 overflow-y-auto py-4">
        {/* Common Dashboard */}
        <NavItem page="dashboard" icon={LayoutDashboard} label="Dashboard" />

        {/* Admin / Super Admin Views */}
        {isAdminOrSuper && (
          <NavItem page="lead-pool" icon={Users} label="Lead Pool" />
        )}

        {/* Super Admin Only */}
        {isSuperAdmin && (
          <NavItem page="employees" icon={Briefcase} label="Employees" />
        )}

        {/* Employee View (Also visible to admins for testing context, but typically mainly for sales) */}
        <NavItem page="my-leads" icon={Phone} label="My Leads" />
      </nav>

      <div className="p-4 border-t border-gray-200">
        <button
          onClick={onLogout}
          className="flex items-center w-full px-4 py-2 text-sm text-red-600 hover:bg-red-50 rounded-md transition-colors"
        >
          <LogOut className="w-4 h-4 mr-2" />
          Sign Out
        </button>
      </div>
    </div>
  );
};

import React, { useEffect, useState } from 'react';
import { Lead, Employee, LeadStatus, EmployeeStatus, Role, RecycleReason } from '../types';
import { mockListLeads, mockListEmployees, mockAssignLeadsToEmployee, mockAutoAssignLeads, mockImportLeads } from '../mock/api';
import { User, UserPlus, Filter, RefreshCw, CheckSquare, Search } from 'lucide-react';

interface LeadPoolProps {
  currentUserRole: Role;
}

export const LeadPool: React.FC<LeadPoolProps> = ({ currentUserRole }) => {
  const [leads, setLeads] = useState<Lead[]>([]);
  const [employees, setEmployees] = useState<Employee[]>([]);
  const [loading, setLoading] = useState(false);
  const [selectedLeadIds, setSelectedLeadIds] = useState<Set<string>>(new Set());

  // Filters
  const [filterRecycled, setFilterRecycled] = useState(false);

  // Assign Modal
  const [showAssignModal, setShowAssignModal] = useState(false);
  const [assignTargetId, setAssignTargetId] = useState('');

  const fetchData = async () => {
    setLoading(true);
    try {
      // Admin sees all leads, effectively
      const allLeads = await mockListLeads();
      // Filter for pool view (Unassigned OR Recycled OR just everything for admin overview)
      // Usually Pool means Unassigned, but admins want to see everything potentially. 
      // Let's filter to UNASSIGNED by default for "Distribution", but allow seeing others.
      // For this requirement: "Imported leads enter pool".
      setLeads(allLeads);

      const allEmps = await mockListEmployees();
      setEmployees(allEmps.filter(e => e.status === EmployeeStatus.ACTIVE && e.role !== Role.SUPER_ADMIN));
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchData();
  }, []);

  const handleImportMock = async () => {
    setLoading(true);
    await mockImportLeads([
      { name: 'New Imported Lead 1', phone: '13333333331', source: 'Excel', batchId: `BATCH_${Date.now()}` },
      { name: 'New Imported Lead 2', phone: '13333333332', source: 'Excel', batchId: `BATCH_${Date.now()}` },
      { name: 'New Imported Lead 3', phone: '13333333333', source: 'Excel', batchId: `BATCH_${Date.now()}` },
    ]);
    await fetchData();
  };

  const handleAutoAssign = async () => {
    if(!confirm("Auto-distribute all UNASSIGNED leads to ACTIVE employees?")) return;
    setLoading(true);
    const res = await mockAutoAssignLeads();
    alert(`Assigned ${res.assignedCount} leads.`);
    await fetchData();
  };

  const handleManualAssign = async () => {
    if (!assignTargetId) return alert("Select an employee");
    setLoading(true);
    await mockAssignLeadsToEmployee(Array.from(selectedLeadIds), assignTargetId);
    setShowAssignModal(false);
    setSelectedLeadIds(new Set());
    setAssignTargetId('');
    await fetchData();
  };

  const toggleSelect = (id: string) => {
    const newSet = new Set(selectedLeadIds);
    if (newSet.has(id)) newSet.delete(id);
    else newSet.add(id);
    setSelectedLeadIds(newSet);
  };

  // Filter Logic
  const filteredLeads = leads.filter(l => {
    if (filterRecycled && !l.recycledAt) return false;
    // Default view: Unassigned only? Or All? 
    // Requirement: "Recycled leads visible in pool".
    // Let's show all, but prioritize UNASSIGNED at top usually.
    return true;
  });

  // Derived state for table
  const tableLeads = filteredLeads.filter(l => l.status === LeadStatus.UNASSIGNED || filterRecycled);

  return (
    <div className="p-8">
      <div className="flex justify-between items-center mb-6">
        <div>
          <h2 className="text-2xl font-bold text-gray-800">Lead Pool</h2>
          <p className="text-gray-500 text-sm">Manage unassigned and recycled leads</p>
        </div>
        <div className="flex gap-3">
          <button 
            onClick={handleImportMock}
            className="flex items-center px-4 py-2 bg-white border border-gray-300 rounded-lg hover:bg-gray-50 text-sm font-medium"
          >
            <UserPlus className="w-4 h-4 mr-2" />
            Import Mock Batch
          </button>
          <button 
            onClick={handleAutoAssign}
            className="flex items-center px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 text-sm font-medium"
          >
            <RefreshCw className="w-4 h-4 mr-2" />
            Auto Assign
          </button>
        </div>
      </div>

      {/* Filters & Actions */}
      <div className="bg-white p-4 rounded-lg shadow-sm border border-gray-200 mb-6 flex justify-between items-center">
        <div className="flex items-center gap-4">
          <div className="flex items-center gap-2">
            <Filter className="w-4 h-4 text-gray-400" />
            <span className="text-sm font-medium text-gray-700">Filters:</span>
          </div>
          <label className="flex items-center gap-2 text-sm text-gray-600 cursor-pointer select-none">
            <input 
              type="checkbox" 
              checked={filterRecycled} 
              onChange={e => setFilterRecycled(e.target.checked)}
              className="rounded text-indigo-600 focus:ring-indigo-500" 
            />
            Show Recycled Only
          </label>
        </div>

        {selectedLeadIds.size > 0 && (
          <div className="flex items-center gap-4 bg-indigo-50 px-4 py-2 rounded-md">
            <span className="text-sm font-medium text-indigo-700">{selectedLeadIds.size} Selected</span>
            <button 
              onClick={() => setShowAssignModal(true)}
              className="text-sm bg-indigo-600 text-white px-3 py-1.5 rounded-md hover:bg-indigo-700"
            >
              Assign to Employee
            </button>
          </div>
        )}
      </div>

      {/* Table */}
      <div className="bg-white rounded-lg shadow overflow-hidden border border-gray-200">
        <div className="overflow-x-auto">
          <table className="min-w-full divide-y divide-gray-200">
            <thead className="bg-gray-50">
              <tr>
                <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider w-10">
                  <input 
                    type="checkbox" 
                    onChange={(e) => {
                      if(e.target.checked) setSelectedLeadIds(new Set(tableLeads.map(l => l.id)));
                      else setSelectedLeadIds(new Set());
                    }}
                    checked={tableLeads.length > 0 && selectedLeadIds.size === tableLeads.length}
                    className="rounded border-gray-300 text-indigo-600 focus:ring-indigo-500"
                  />
                </th>
                <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Lead Info</th>
                <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Source/Batch</th>
                <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Status</th>
                <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Recycle Info</th>
                <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Created</th>
              </tr>
            </thead>
            <tbody className="bg-white divide-y divide-gray-200">
              {tableLeads.length === 0 ? (
                <tr><td colSpan={6} className="px-6 py-12 text-center text-gray-500">No unassigned/recycled leads found.</td></tr>
              ) : (
                tableLeads.map((lead) => (
                  <tr key={lead.id} className="hover:bg-gray-50 transition-colors">
                    <td className="px-6 py-4 whitespace-nowrap">
                      <input 
                        type="checkbox" 
                        checked={selectedLeadIds.has(lead.id)}
                        onChange={() => toggleSelect(lead.id)}
                        className="rounded border-gray-300 text-indigo-600 focus:ring-indigo-500"
                      />
                    </td>
                    <td className="px-6 py-4">
                      <div className="text-sm font-medium text-gray-900">{lead.name}</div>
                      <div className="text-sm text-gray-500">{lead.phone}</div>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      <div className="text-sm text-gray-900">{lead.source}</div>
                      <div className="text-xs text-gray-400">{lead.batchId}</div>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      <span className={`px-2 inline-flex text-xs leading-5 font-semibold rounded-full 
                        ${lead.status === LeadStatus.UNASSIGNED ? 'bg-yellow-100 text-yellow-800' : 'bg-gray-100 text-gray-800'}`}>
                        {lead.status}
                      </span>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      {lead.recycledAt ? (
                        <div>
                          <div className="text-xs font-bold text-red-600">{lead.recycleReason}</div>
                          <div className="text-xs text-gray-500">{new Date(lead.recycledAt).toLocaleDateString()}</div>
                        </div>
                      ) : <span className="text-gray-400">-</span>}
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                      {new Date(lead.createdAt).toLocaleDateString()}
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* Manual Assign Modal */}
      {showAssignModal && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white rounded-lg p-6 w-96 shadow-xl transform transition-all">
            <h3 className="text-lg font-bold mb-4">Assign {selectedLeadIds.size} Leads</h3>
            <div className="mb-4">
              <label className="block text-sm font-medium text-gray-700 mb-1">Select Employee</label>
              <select 
                value={assignTargetId}
                onChange={(e) => setAssignTargetId(e.target.value)}
                className="w-full border border-gray-300 rounded-md shadow-sm p-2 focus:ring-indigo-500 focus:border-indigo-500"
              >
                <option value="">-- Select --</option>
                {employees.map(emp => (
                  <option key={emp.id} value={emp.id}>{emp.name} ({emp.assignedLeadsCount} active)</option>
                ))}
              </select>
            </div>
            <div className="flex justify-end gap-3">
              <button 
                onClick={() => setShowAssignModal(false)}
                className="px-4 py-2 text-sm text-gray-700 hover:bg-gray-100 rounded-md"
              >
                Cancel
              </button>
              <button 
                onClick={handleManualAssign}
                disabled={!assignTargetId || loading}
                className="px-4 py-2 text-sm bg-indigo-600 text-white rounded-md hover:bg-indigo-700 disabled:opacity-50"
              >
                {loading ? 'Assigning...' : 'Confirm'}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useEffect, useState } from 'react';
import { Employee, EmployeeStatus } from '../types';
import { mockListEmployees, mockDeactivateEmployee, mockActivateEmployee } from '../mock/api';
import { UserX, UserCheck, AlertTriangle } from 'lucide-react';

export const EmployeeManager: React.FC = () => {
  const [employees, setEmployees] = useState<Employee[]>([]);
  const [loading, setLoading] = useState(false);
  const [deactivateModal, setDeactivateModal] = useState<{ show: boolean, empId: string | null, empName: string }>({ show: false, empId: null, empName: '' });

  const fetchEmployees = async () => {
    setLoading(true);
    try {
      const data = await mockListEmployees();
      setEmployees(data);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchEmployees();
  }, []);

  const handleDeactivateClick = (emp: Employee) => {
    setDeactivateModal({ show: true, empId: emp.id, empName: emp.name });
  };

  const confirmDeactivate = async () => {
    if (!deactivateModal.empId) return;
    setLoading(true);
    try {
      const res = await mockDeactivateEmployee(deactivateModal.empId);
      setDeactivateModal({ show: false, empId: null, empName: '' });
      await fetchEmployees();
      alert(`Employee deactivated. ${res.recycledLeadCount} leads have been recycled to the pool.`);
    } catch (e) {
      alert("Error deactivating employee");
    } finally {
      setLoading(false);
    }
  };

  const handleActivate = async (id: string) => {
    if (!confirm("Re-activate this employee? Leads will NOT be automatically restored.")) return;
    setLoading(true);
    await mockActivateEmployee(id);
    await fetchEmployees();
    setLoading(false);
  };

  return (
    <div className="p-8">
      <div className="mb-6">
        <h2 className="text-2xl font-bold text-gray-800">Employee Management</h2>
        <p className="text-gray-500 text-sm">Manage access and recycle resources for sales staff.</p>
      </div>

      <div className="bg-white rounded-lg shadow overflow-hidden border border-gray-200">
        <table className="min-w-full divide-y divide-gray-200">
          <thead className="bg-gray-50">
            <tr>
              <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Employee</th>
              <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Role</th>
              <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Status</th>
              <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Assigned Leads</th>
              <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Customers</th>
              <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 uppercase tracking-wider">Actions</th>
            </tr>
          </thead>
          <tbody className="bg-white divide-y divide-gray-200">
            {employees.map((emp) => (
              <tr key={emp.id} className={emp.status === EmployeeStatus.INACTIVE ? 'bg-gray-50' : ''}>
                <td className="px-6 py-4 whitespace-nowrap">
                  <div className="flex items-center">
                    <div className="flex-shrink-0 h-10 w-10 rounded-full bg-indigo-100 flex items-center justify-center text-indigo-600 font-bold">
                      {emp.name.charAt(0)}
                    </div>
                    <div className="ml-4">
                      <div className="text-sm font-medium text-gray-900">{emp.name}</div>
                      <div className="text-sm text-gray-500">{emp.email}</div>
                    </div>
                  </div>
                </td>
                <td className="px-6 py-4 whitespace-nowrap">
                  <span className="text-sm text-gray-600 bg-gray-100 px-2 py-1 rounded">{emp.role}</span>
                </td>
                <td className="px-6 py-4 whitespace-nowrap">
                  {emp.status === EmployeeStatus.ACTIVE ? (
                    <span className="px-2 inline-flex text-xs leading-5 font-semibold rounded-full bg-green-100 text-green-800">
                      Active
                    </span>
                  ) : (
                    <span className="px-2 inline-flex text-xs leading-5 font-semibold rounded-full bg-red-100 text-red-800">
                      Inactive
                    </span>
                  )}
                  {emp.leftAt && <div className="text-xs text-red-500 mt-1">Left: {new Date(emp.leftAt).toLocaleDateString()}</div>}
                </td>
                <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                  {emp.assignedLeadsCount}
                </td>
                <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                  {emp.customerCount}
                </td>
                <td className="px-6 py-4 whitespace-nowrap text-right text-sm font-medium">
                  {emp.status === EmployeeStatus.ACTIVE && emp.role !== 'SUPER_ADMIN' && (
                    <button 
                      onClick={() => handleDeactivateClick(emp)}
                      className="text-red-600 hover:text-red-900 flex items-center justify-end gap-1 ml-auto"
                    >
                      <UserX className="w-4 h-4" /> Deactivate
                    </button>
                  )}
                  {emp.status === EmployeeStatus.INACTIVE && (
                    <button 
                      onClick={() => handleActivate(emp.id)}
                      className="text-green-600 hover:text-green-900 flex items-center justify-end gap-1 ml-auto"
                    >
                      <UserCheck className="w-4 h-4" /> Reactivate
                    </button>
                  )}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {/* Confirmation Modal */}
      {deactivateModal.show && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white rounded-lg p-6 w-full max-w-md shadow-2xl">
            <div className="flex items-center gap-3 text-red-600 mb-4">
              <AlertTriangle className="w-8 h-8" />
              <h3 className="text-lg font-bold">Deactivate Employee?</h3>
            </div>
            <p className="text-gray-600 mb-4">
              You are about to deactivate <strong>{deactivateModal.empName}</strong>.
            </p>
            <div className="bg-red-50 p-4 rounded-md mb-6 border border-red-100">
              <h4 className="font-semibold text-red-800 text-sm mb-2">System Actions:</h4>
              <ul className="list-disc list-inside text-sm text-red-700 space-y-1">
                <li>Employee status becomes INACTIVE.</li>
                <li>All ASSIGNED/FOLLOWING leads will be <strong>recycled</strong>.</li>
                <li>Recycled leads return to the <strong>Unassigned Pool</strong>.</li>
              </ul>
            </div>
            <div className="flex justify-end gap-3">
              <button 
                onClick={() => setDeactivateModal({ show: false, empId: null, empName: '' })}
                className="px-4 py-2 text-sm text-gray-700 hover:bg-gray-100 rounded-md"
              >
                Cancel
              </button>
              <button 
                onClick={confirmDeactivate}
                className="px-4 py-2 text-sm bg-red-600 text-white rounded-md hover:bg-red-700 shadow-sm"
              >
                Confirm Deactivate
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useEffect, useState } from 'react';
import { Lead, LeadStatus, FollowUp } from '../types';
import { mockListLeads, mockGetFollowUps, mockAddFollowUp, mockUpdateLeadStatus } from '../mock/api';
import { Phone, Clock, MessageSquare, CheckCircle, XCircle } from 'lucide-react';

interface MyLeadsProps {
  currentUserId: string;
}

export const MyLeads: React.FC<MyLeadsProps> = ({ currentUserId }) => {
  const [leads, setLeads] = useState<Lead[]>([]);
  const [selectedLead, setSelectedLead] = useState<Lead | null>(null);
  const [followUps, setFollowUps] = useState<FollowUp[]>([]);
  const [loading, setLoading] = useState(false);
  const [newNote, setNewNote] = useState('');

  const fetchLeads = async () => {
    setLoading(true);
    const data = await mockListLeads({ ownerId: currentUserId });
    setLeads(data.filter(l => l.status !== LeadStatus.DEAL && l.status !== LeadStatus.INVALID));
    setLoading(false);
  };

  useEffect(() => {
    fetchLeads();
  }, [currentUserId]);

  const handleSelectLead = async (lead: Lead) => {
    setSelectedLead(lead);
    setNewNote('');
    // Mock fetch followups
    const history = await mockGetFollowUps(lead.id);
    setFollowUps(history);
  };

  const handleStatusChange = async (newStatus: LeadStatus) => {
    if (!selectedLead) return;

    let dealName = '';
    if (newStatus === LeadStatus.DEAL) {
      dealName = prompt("Enter Deal/Customer Name:", selectedLead.name) || selectedLead.name;
    }

    await mockUpdateLeadStatus(selectedLead.id, newStatus, { name: dealName });
    await fetchLeads();
    setSelectedLead(null); // Deselect as it might disappear from list
  };

  const handleSubmitNote = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedLead || !newNote.trim()) return;

    await mockAddFollowUp(selectedLead.id, currentUserId, newNote);

    // Auto status update to FOLLOWING if it was ASSIGNED
    if (selectedLead.status === LeadStatus.ASSIGNED) {
      await mockUpdateLeadStatus(selectedLead.id, LeadStatus.FOLLOWING);
    }

    setNewNote('');
    const updatedHistory = await mockGetFollowUps(selectedLead.id);
    setFollowUps(updatedHistory);
    // Refresh leads to update timestamps or status
    fetchLeads();
  };

  return (
    <div className="flex h-[calc(100vh-64px)] overflow-hidden">
      {/* List Column */}
      <div className="w-1/3 border-r border-gray-200 bg-white overflow-y-auto">
        <div className="p-4 border-b border-gray-100 bg-gray-50 sticky top-0">
          <h2 className="font-bold text-gray-700">My Work List ({leads.length})</h2>
        </div>
        <div>
          {leads.length === 0 ? (
            <div className="p-8 text-center text-gray-400">
              No active leads. Ask admin for assignment.
            </div>
          ) : (
            leads.map(lead => (
              <div 
                key={lead.id}
                onClick={() => handleSelectLead(lead)}
                className={`p-4 border-b border-gray-100 cursor-pointer hover:bg-blue-50 transition-colors ${selectedLead?.id === lead.id ? 'bg-blue-50 border-l-4 border-l-blue-500' : ''}`}
              >
                <div className="flex justify-between items-start mb-1">
                  <span className="font-medium text-gray-900">{lead.name}</span>
                  <span className={`text-xs px-2 py-0.5 rounded-full ${lead.status === 'FOLLOWING' ? 'bg-blue-100 text-blue-700' : 'bg-gray-100 text-gray-600'}`}>
                    {lead.status}
                  </span>
                </div>
                <div className="flex items-center text-sm text-gray-500 mb-2">
                  <Phone className="w-3 h-3 mr-1" /> {lead.phone}
                </div>
                <div className="text-xs text-gray-400">
                  Updated: {new Date(lead.updatedAt).toLocaleDateString()}
                </div>
              </div>
            ))
          )}
        </div>
      </div>

      {/* Detail Column */}
      <div className="flex-1 bg-gray-50 overflow-y-auto p-6">
        {selectedLead ? (
          <div className="max-w-2xl mx-auto">
            {/* Header Card */}
            <div className="bg-white p-6 rounded-lg shadow-sm border border-gray-200 mb-6">
              <div className="flex justify-between items-start">
                <div>
                  <h1 className="text-2xl font-bold text-gray-900 mb-2">{selectedLead.name}</h1>
                  <div className="flex items-center gap-4 text-sm text-gray-600">
                    <span className="flex items-center"><Phone className="w-4 h-4 mr-1"/> {selectedLead.phone}</span>
                    <span className="bg-gray-100 px-2 py-0.5 rounded">Source: {selectedLead.source}</span>
                  </div>
                </div>
                <div className="flex gap-2">
                  <button 
                    onClick={() => handleStatusChange(LeadStatus.DEAL)}
                    className="flex items-center px-3 py-2 bg-green-600 text-white rounded hover:bg-green-700 transition"
                  >
                    <CheckCircle className="w-4 h-4 mr-2" /> Convert Deal
                  </button>
                  <button 
                    onClick={() => handleStatusChange(LeadStatus.INVALID)}
                    className="flex items-center px-3 py-2 bg-gray-200 text-gray-700 rounded hover:bg-gray-300 transition"
                  >
                    <XCircle className="w-4 h-4 mr-2" /> Invalid
                  </button>
                </div>
              </div>
            </div>

            {/* Timeline / FollowUp */}
            <div className="bg-white rounded-lg shadow-sm border border-gray-200 p-6">
              <h3 className="font-bold text-gray-800 mb-4 flex items-center">
                <Clock className="w-4 h-4 mr-2" /> Activity Timeline
              </h3>

              {/* Input */}
              <form onSubmit={handleSubmitNote} className="mb-8">
                <textarea
                  value={newNote}
                  onChange={e => setNewNote(e.target.value)}
                  placeholder="Record call summary or next steps..."
                  className="w-full p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none resize-none h-24"
                ></textarea>
                <div className="flex justify-end mt-2">
                  <button 
                    type="submit"
                    disabled={!newNote.trim()}
                    className="bg-blue-600 text-white px-4 py-2 rounded-md hover:bg-blue-700 text-sm font-medium disabled:opacity-50"
                  >
                    Add Record
                  </button>
                </div>
              </form>

              {/* List */}
              <div className="space-y-6">
                {followUps.map(fu => (
                  <div key={fu.id} className="relative pl-8 pb-4 border-l-2 border-gray-100 last:border-0">
                    <div className="absolute left-[-9px] top-0 w-4 h-4 rounded-full bg-blue-100 border-2 border-white"></div>
                    <div className="text-xs text-gray-400 mb-1">{new Date(fu.createdAt).toLocaleString()}</div>
                    <div className="text-gray-800 text-sm bg-gray-50 p-3 rounded-lg border border-gray-100">
                      {fu.content}
                    </div>
                  </div>
                ))}
                {followUps.length === 0 && <p className="text-gray-400 text-sm text-center">No history yet.</p>}
              </div>
            </div>
          </div>
        ) : (
          <div className="h-full flex flex-col items-center justify-center text-gray-400">
            <MessageSquare className="w-16 h-16 mb-4 opacity-20" />
            <p>Select a lead to start tracking</p>
          </div>
        )}
      </div>
    </div>
  );
};

