import React, { useEffect, useState } from 'react';
import { Lead, Employee, LeadStatus, EmployeeStatus, Role, RecycleReason } from '../types';
import { mockListLeads, mockListEmployees, mockAssignLeadsToEmployee, mockAutoAssignLeads, mockImportLeads } from '../mock/api';
import { User, UserPlus, Filter, RefreshCw, CheckSquare, Search } from 'lucide-react';

interface LeadPoolProps {
  currentUserRole: Role;
}

export const LeadPool: React.FC<LeadPoolProps> = ({ currentUserRole }) => {
  const [leads, setLeads] = useState<Lead[]>([]);
  const [employees, setEmployees] = useState<Employee[]>([]);
  const [loading, setLoading] = useState(false);
  const [selectedLeadIds, setSelectedLeadIds] = useState<Set<string>>(new Set());

  // Filters
  const [filterRecycled, setFilterRecycled] = useState(false);

  // Assign Modal
  const [showAssignModal, setShowAssignModal] = useState(false);
  const [assignTargetId, setAssignTargetId] = useState('');

  const fetchData = async () => {
    setLoading(true);
    try {
      // Admin sees all leads, effectively
      const allLeads = await mockListLeads();
      setLeads(allLeads);

      const allEmps = await mockListEmployees();
      setEmployees(allEmps.filter(e => e.status === EmployeeStatus.ACTIVE && e.role !== Role.SUPER_ADMIN));
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchData();
  }, []);

  const handleImportMock = async () => {
    setLoading(true);
    await mockImportLeads([
      { name: '模拟导入客户-A', phone: '13333333331', source: 'Excel导入', batchId: `批次_${Date.now()}` },
      { name: '模拟导入客户-B', phone: '13333333332', source: 'Excel导入', batchId: `批次_${Date.now()}` },
      { name: '模拟导入客户-C', phone: '13333333333', source: 'Excel导入', batchId: `批次_${Date.now()}` },
    ]);
    await fetchData();
    alert('成功导入 3 条模拟线索！');
  };

  const handleAutoAssign = async () => {
    if(!confirm("确定要将所有【待分配】状态的线索，自动轮询分配给【在职】员工吗？")) return;
    setLoading(true);
    const res = await mockAutoAssignLeads();
    alert(`分配完成，共分配了 ${res.assignedCount} 条线索。`);
    await fetchData();
  };

  const handleManualAssign = async () => {
    if (!assignTargetId) return alert("请选择一名员工");
    setLoading(true);
    await mockAssignLeadsToEmployee(Array.from(selectedLeadIds), assignTargetId);
    setShowAssignModal(false);
    setSelectedLeadIds(new Set());
    setAssignTargetId('');
    await fetchData();
    alert('线索分配成功！');
