import React, { useState, useEffect } from 'react';
import { UserSession, Role } from './types';
import { Sidebar } from './components/Sidebar';
import { Login } from './pages/Login';
import { LeadPool } from './pages/LeadPool';
import { EmployeeManager } from './pages/EmployeeManager';
import { MyLeads } from './pages/MyLeads';

const App: React.FC = () => {
  const [user, setUser] = useState<UserSession | null>(null);
  const [currentPage, setCurrentPage] = useState('dashboard');

  // Load session from local storage to survive refreshes (optional for prototype, but nice)
  useEffect(() => {
    const saved = localStorage.getItem('crm_user');
    if (saved) {
      setUser(JSON.parse(saved));
    }
  }, []);

  const handleLogin = (session: UserSession) => {
    setUser(session);
    localStorage.setItem('crm_user', JSON.stringify(session));
    // Default redirects
    if (session.role === Role.EMPLOYEE) setCurrentPage('my-leads');
    else setCurrentPage('dashboard');
  };

  const handleLogout = () => {
    setUser(null);
    localStorage.removeItem('crm_user');
    setCurrentPage('dashboard');
  };

  if (!user) {
    return <Login onLogin={handleLogin} />;
  }

  // Simple Router Switch
  const renderPage = () => {
    switch (currentPage) {
      case 'dashboard':
        return (
          <div className="p-8">
            <h1 className="text-3xl font-bold text-gray-800 mb-4">欢迎回来, {user.name}</h1>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
              <div className="bg-white p-6 rounded-lg shadow border border-gray-200">
                <h3 className="text-gray-500 text-sm font-medium">系统状态</h3>
                <p className="text-2xl font-bold mt-2 text-gray-800">运行正常</p>
                <p className="text-sm text-gray-400 mt-1">Mock 接口响应中</p>
              </div>
            </div>
            {/* Helpful navigation hints for the prototype user */}
            <div className="mt-8 bg-blue-50 p-6 rounded-lg border border-blue-100">
              <h3 className="font-bold text-blue-800 mb-2">原型操作指引:</h3>
              <ul className="list-disc list-inside text-blue-700 space-y-1">
                {user.role === Role.SUPER_ADMIN && (
                  <li>前往 <strong>员工管理</strong>：操作员工离职，系统将自动回收其名下线索。</li>
                )}
                {(user.role === Role.ADMIN || user.role === Role.SUPER_ADMIN) && (
                  <li>前往 <strong>线索公海池</strong>：模拟导入数据，或进行手动/自动线索分配。</li>
                )}
                <li>前往 <strong>我的线索</strong>：以销售视角进行线索跟进、记录、或转成交。</li>
              </ul>
            </div>
          </div>
        );
      case 'lead-pool':
        return <LeadPool currentUserRole={user.role} />;
      case 'employees':
        if (user.role !== Role.SUPER_ADMIN) return <div className="p-8 text-red-500">无权访问</div>;
        return <EmployeeManager />;
      case 'my-leads':
        return <MyLeads currentUserId={user.id} />;
      default:
        return <div>页面不存在</div>;
    }
  };

  return (
    <div className="flex bg-gray-50 min-h-screen font-sans">
      <Sidebar 
        user={user} 
        currentPage={currentPage} 
        onNavigate={setCurrentPage} 
        onLogout={handleLogout} 
      />
      <main className="ml-64 flex-1">
        {renderPage()}
      </main>
    </div>
  );
};

export default App;

import React, { useEffect, useState } from 'react';
import { Lead, Employee, LeadStatus, EmployeeStatus, Role, RecycleReason } from '../types';
import { mockListLeads, mockListEmployees, mockAssignLeadsToEmployee, mockAutoAssignLeads, mockImportLeads } from '../mock/api';
import { User, UserPlus, Filter, RefreshCw, CheckSquare, Search } from 'lucide-react';

interface LeadPoolProps {
  currentUserRole: Role;
}

export const LeadPool: React.FC<LeadPoolProps> = ({ currentUserRole }) => {
  const [leads, setLeads] = useState<Lead[]>([]);
  const [employees, setEmployees] = useState<Employee[]>([]);
  const [loading, setLoading] = useState(false);
  const [selectedLeadIds, setSelectedLeadIds] = useState<Set<string>>(new Set());

  // Filters
  const [filterRecycled, setFilterRecycled] = useState(false);

  // Assign Modal
  const [showAssignModal, setShowAssignModal] = useState(false);
  const [assignTargetId, setAssignTargetId] = useState('');

  const fetchData = async () => {
    setLoading(true);
    try {
      // Admin sees all leads, effectively
      const allLeads = await mockListLeads();
      setLeads(allLeads);

      const allEmps = await mockListEmployees();
      setEmployees(allEmps.filter(e => e.status === EmployeeStatus.ACTIVE && e.role !== Role.SUPER_ADMIN));
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchData();
  }, []);

  const handleImportMock = async () => {
    setLoading(true);
    await mockImportLeads([
      { name: '模拟导入客户-A', phone: '13333333331', source: 'Excel导入', batchId: `批次_${Date.now()}` },
      { name: '模拟导入客户-B', phone: '13333333332', source: 'Excel导入', batchId: `批次_${Date.now()}` },
      { name: '模拟导入客户-C', phone: '13333333333', source: 'Excel导入', batchId: `批次_${Date.now()}` },
    ]);
    await fetchData();
    alert('成功导入 3 条模拟线索！');
  };

  const handleAutoAssign = async () => {
    if(!confirm("确定要将所有【待分配】状态的线索，自动轮询分配给【在职】员工吗？")) return;
    setLoading(true);
    const res = await mockAutoAssignLeads();
    alert(`分配完成，共分配了 ${res.assignedCount} 条线索。`);
    await fetchData();
  };

  const handleManualAssign = async () => {
    if (!assignTargetId) return alert("请选择一名员工");

    const targetEmployee = employees.find(e => e.id === assignTargetId);
    const empName = targetEmployee ? targetEmployee.name : '未知员工';

    if (!confirm(`您确定要将选中的 ${selectedLeadIds.size} 条线索分配给员工【${empName}】吗？`)) {
        return;
    }

    setLoading(true);
    await mockAssignLeadsToEmployee(Array.from(selectedLeadIds), assignTargetId);
    setShowAssignModal(false);
    setSelectedLeadIds(new Set());
    setAssignTargetId('');
    await fetchData();
    alert(`成功将线索分配给 ${empName}！`);
  };

  const toggleSelect = (id: string) => {
    const newSet = new Set(selectedLeadIds);
    if (newSet.has(id)) newSet.delete(id);
    else newSet.add(id);
    setSelectedLeadIds(newSet);
  };

  // Filter Logic
  const filteredLeads = leads.filter(l => {
    if (filterRecycled && !l.recycledAt) return false;
    return true;
  });

  // Derived state for table
  const tableLeads = filteredLeads.filter(l => l.status === LeadStatus.UNASSIGNED || filterRecycled);

  const getStatusLabel = (status: LeadStatus) => {
    switch (status) {
      case LeadStatus.UNASSIGNED: return '待分配';
      case LeadStatus.ASSIGNED: return '已分配';
      case LeadStatus.FOLLOWING: return '跟进中';
      case LeadStatus.DEAL: return '已成交';
      case LeadStatus.INVALID: return '无效';
      default: return status;
    }
  };

  const getRecycleReasonLabel = (reason?: RecycleReason) => {
    if (reason === RecycleReason.EMPLOYEE_LEFT) return '员工离职回收';
    if (reason === RecycleReason.MANUAL) return '手动回收';
    return reason;
  };

  return (
    <div className="p-8">
      <div className="flex justify-between items-center mb-6">
        <div>
          <h2 className="text-2xl font-bold text-gray-800">线索公海池</h2>
          <p className="text-gray-500 text-sm">管理待分配及回收的线索资源</p>
        </div>
        <div className="flex gap-3">
          <button 
            onClick={handleImportMock}
            className="flex items-center px-4 py-2 bg-white border border-gray-300 rounded-lg hover:bg-gray-50 text-sm font-medium"
          >
            <UserPlus className="w-4 h-4 mr-2" />
            模拟导入线索
          </button>
          <button 
            onClick={handleAutoAssign}
            className="flex items-center px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 text-sm font-medium"
          >
            <RefreshCw className="w-4 h-4 mr-2" />
            一键自动分配
          </button>
        </div>
      </div>

      {/* Filters & Actions */}
      <div className="bg-white p-4 rounded-lg shadow-sm border border-gray-200 mb-6 flex justify-between items-center">
        <div className="flex items-center gap-4">
          <div className="flex items-center gap-2">
            <Filter className="w-4 h-4 text-gray-400" />
            <span className="text-sm font-medium text-gray-700">筛选:</span>
          </div>
          <label className="flex items-center gap-2 text-sm text-gray-600 cursor-pointer select-none">
            <input 
              type="checkbox" 
              checked={filterRecycled} 
              onChange={e => setFilterRecycled(e.target.checked)}
              className="rounded text-indigo-600 focus:ring-indigo-500" 
            />
            仅显示回收线索
          </label>
        </div>

        {selectedLeadIds.size > 0 && (
          <div className="flex items-center gap-4 bg-indigo-50 px-4 py-2 rounded-md">
            <span className="text-sm font-medium text-indigo-700">已选中 {selectedLeadIds.size} 条</span>
            <button 
              onClick={() => setShowAssignModal(true)}
              className="text-sm bg-indigo-600 text-white px-3 py-1.5 rounded-md hover:bg-indigo-700"
            >
              分配给员工
            </button>
          </div>
        )}
      </div>

      {/* Table */}
      <div className="bg-white rounded-lg shadow overflow-hidden border border-gray-200">
        <div className="overflow-x-auto">
          <table className="min-w-full divide-y divide-gray-200">
            <thead className="bg-gray-50">
              <tr>
                <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider w-10">
                  <input 
                    type="checkbox" 
                    onChange={(e) => {
                      if(e.target.checked) setSelectedLeadIds(new Set(tableLeads.map(l => l.id)));
                      else setSelectedLeadIds(new Set());
                    }}
                    checked={tableLeads.length > 0 && selectedLeadIds.size === tableLeads.length}
                    className="rounded border-gray-300 text-indigo-600 focus:ring-indigo-500"
                  />
                </th>
                <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">线索信息</th>
                <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">来源/批次</th>
                <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">状态</th>
                <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">回收信息</th>
                <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">创建时间</th>
