export const LeadPool: React.FC<LeadPoolProps> = ({ currentUserRole }) => {
  const [leads, setLeads] = useState<Lead[]>([]);
  const [employees, setEmployees] = useState<Employee[]>([]);
  const [loading, setLoading] = useState(false);
  const [selectedLeadIds, setSelectedLeadIds] = useState<Set<string>>(new Set());

  // Filters
  const [filterRecycled, setFilterRecycled] = useState(false);

  // Modals
  const [showAssignModal, setShowAssignModal] = useState(false);
  const [showConfirmModal, setShowConfirmModal] = useState(false);
  const [showImportModal, setShowImportModal] = useState(false); // Import Modal

  const [assignTargetId, setAssignTargetId] = useState('');

  // File Upload State
  const [selectedFile, setSelectedFile] = useState<File | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const fetchData = async () => {
    setLoading(true);
    try {
      const allLeads = await mockListLeads();
      setLeads(allLeads);

      const allEmps = await mockListEmployees();
      setEmployees(allEmps.filter(e => e.status === EmployeeStatus.ACTIVE && e.role !== Role.SUPER_ADMIN));
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchData();
  }, []);

  // --- Import Logic ---
  const handleOpenImport = () => {
    setSelectedFile(null);
    setShowImportModal(true);
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      setSelectedFile(e.target.files[0]);
    }
  };

  const handleExecuteImport = async () => {
    if (!selectedFile) {
      alert("请先选择一个文件！");
      return;
    }

    setLoading(true);
    try {
      // Prepare mock data from the static list
      const batchId = `导入批次_${new Date().toISOString().slice(0, 10)}`;
      const newLeads = STATIC_IMPORT_DATA.map(item => ({
        name: item.name,
        phone: item.phone,
        region: item.region,
        source: 'Excel导入',
        batchId: batchId
      }));

      await mockImportLeads(newLeads);
      await fetchData();

      setShowImportModal(false);
      setSelectedFile(null);
      alert(`成功导入 ${newLeads.length} 条线索！`);
    } catch (error) {
      console.error(error);
      alert("导入失败");
    } finally {
      setLoading(false);
    }
  };

  // --- Assignment Logic ---

  const handleAutoAssign = async () => {
    if(!window.confirm("确定要将所有【待分配】状态的线索，自动轮询分配给【在职】员工吗？")) return;
    setLoading(true);
    const res = await mockAutoAssignLeads();
    alert(`分配完成，共分配了 ${res.assignedCount} 条线索。`);
    await fetchData();
    setLoading(false);
  };

  const handlePreAssign = () => {
    if (!assignTargetId) {
      alert("请先从下拉列表中选择一名接收线索的员工！");
      return;
    }
    if (selectedLeadIds.size === 0) {
      alert("未选择任何线索！");
      return;
    }
    setShowAssignModal(false);
    setShowConfirmModal(true);
  };

  const handleExecuteAssign = async () => {
    setLoading(true);
    try {
        const targetEmployee = employees.find(e => e.id === assignTargetId);
        const empName = targetEmployee ? targetEmployee.name : '未知员工';

        await mockAssignLeadsToEmployee(Array.from(selectedLeadIds), assignTargetId);

        setShowConfirmModal(false);
        setSelectedLeadIds(new Set());
        setAssignTargetId('');

        await fetchData();
        setTimeout(() => alert(`分配成功！已将 ${selectedLeadIds.size} 条线索分配给 ${empName}。`), 100);
    } catch (error) {
        console.error(error);
        alert("分配失败，请稍后重试。");
    } finally {
        setLoading(false);
    }
  };

  const toggleSelect = (id: string) => {
    const newSet = new Set(selectedLeadIds);
    if (newSet.has(id)) newSet.delete(id);
    else newSet.add(id);
    setSelectedLeadIds(newSet);
  };

  // Filter Logic
  const filteredLeads = leads.filter(l => {
    if (filterRecycled && !l.recycledAt) return false;
    return true;
  });

  const tableLeads = filteredLeads.filter(l => l.status === LeadStatus.UNASSIGNED || filterRecycled);

  const getStatusLabel = (status: LeadStatus) => {
    switch (status) {
      case LeadStatus.UNASSIGNED: return '待分配';
      case LeadStatus.ASSIGNED: return '已分配';
      case LeadStatus.FOLLOWING: return '跟进中';
      case LeadStatus.DEAL: return '已成交';
      case LeadStatus.INVALID: return '无效';
      default: return status;
    }
  };

  const getRecycleReasonLabel = (reason?: RecycleReason) => {
    if (reason === RecycleReason.EMPLOYEE_LEFT) return '员工离职回收';
    if (reason === RecycleReason.MANUAL) return '手动回收';
    return reason;
  };

  const targetEmployeeName = employees.find(e => e.id === assignTargetId)?.name || '未知员工';

  return (
    <div className="p-8">
      <div className="flex justify-between items-center mb-6">
        <div>
          <h2 className="text-2xl font-bold text-gray-800">线索公海池</h2>
          <p className="text-gray-500 text-sm">管理待分配及回收的线索资源</p>
        </div>
        <div className="flex gap-3">
          <button 
            onClick={handleOpenImport}
            disabled={loading}
            className="flex items-center px-4 py-2 bg-white border border-gray-300 rounded-lg hover:bg-gray-50 text-sm font-medium disabled:opacity-50"
          >
            <UploadCloud className="w-4 h-4 mr-2" />
            导入线索
          </button>
          <button 
            onClick={handleAutoAssign}
            disabled={loading}
            className="flex items-center px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 text-sm font-medium disabled:opacity-50"
          >
            <RefreshCw className="w-4 h-4 mr-2" />
            一键自动分配
          </button>
        </div>
      </div>

      {/* Filters & Actions */}
      <div className="bg-white p-4 rounded-lg shadow-sm border border-gray-200 mb-6 flex justify-between items-center">
        <div className="flex items-center gap-4">
          <div className="flex items-center gap-2">
            <Filter className="w-4 h-4 text-gray-400" />
            <span className="text-sm font-medium text-gray-700">筛选:</span>
          </div>
          <label className="flex items-center gap-2 text-sm text-gray-600 cursor-pointer select-none">
            <input 
              type="checkbox" 
              checked={filterRecycled} 
              onChange={e => setFilterRecycled(e.target.checked)}
              className="rounded text-indigo-600 focus:ring-indigo-500" 
            />
            仅显示回收线索
          </label>
        </div>

        {selectedLeadIds.size > 0 && (
          <div className="flex items-center gap-4 bg-indigo-50 px-4 py-2 rounded-md">
            <span className="text-sm font-medium text-indigo-700">已选中 {selectedLeadIds.size} 条</span>
            <button 
              onClick={() => setShowAssignModal(true)}
              className="text-sm bg-indigo-600 text-white px-3 py-1.5 rounded-md hover:bg-indigo-700"
            >
              分配给员工
            </button>
          </div>
        )}
      </div>

      {/* Table */}
      <div className="bg-white rounded-lg shadow overflow-hidden border border-gray-200">
        <div className="overflow-x-auto">
          <table className="min-w-full divide-y divide-gray-200">
            <thead className="bg-gray-50">
              <tr>
                <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider w-10">
                  <input 
                    type="checkbox" 
                    onChange={(e) => {
                      if(e.target.checked) setSelectedLeadIds(new Set(tableLeads.map(l => l.id)));
                      else setSelectedLeadIds(new Set());
                    }}
                    checked={tableLeads.length > 0 && selectedLeadIds.size === tableLeads.length}
                    className="rounded border-gray-300 text-indigo-600 focus:ring-indigo-500"
                  />
                </th>
                <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">线索信息</th>
                <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">地区</th>
                <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">来源/批次</th>
                <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">状态</th>
                <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">回收信息</th>
                <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">创建时间</th>
              </tr>
            </thead>
            <tbody className="bg-white divide-y divide-gray-200">
              {tableLeads.length === 0 ? (
                <tr><td colSpan={7} className="px-6 py-12 text-center text-gray-500">暂无符合条件的线索。</td></tr>
              ) : (
                tableLeads.map((lead) => (
                  <tr key={lead.id} className="hover:bg-gray-50 transition-colors">
                    <td className="px-6 py-4 whitespace-nowrap">
                      <input 
                        type="checkbox" 
                        checked={selectedLeadIds.has(lead.id)}
                        onChange={() => toggleSelect(lead.id)}
                        className="rounded border-gray-300 text-indigo-600 focus:ring-indigo-500"
                      />
                    </td>
                    <td className="px-6 py-4">
                      <div className="text-sm font-medium text-gray-900">{lead.name}</div>
                      <div className="text-sm text-gray-500">{lead.phone}</div>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap">
                       {/* Region Display */}
                       <div className="text-sm text-gray-700">{lead.region || '-'}</div>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      <div className="text-sm text-gray-900">{lead.source}</div>
                      <div className="text-xs text-gray-400">{lead.batchId}</div>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      <span className={`px-2 inline-flex text-xs leading-5 font-semibold rounded-full 
                        ${lead.status === LeadStatus.UNASSIGNED ? 'bg-yellow-100 text-yellow-800' : 'bg-gray-100 text-gray-800'}`}>
                        {getStatusLabel(lead.status)}
                      </span>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      {lead.recycledAt ? (
                        <div>
                          <div className="text-xs font-bold text-red-600">{getRecycleReasonLabel(lead.recycleReason)}</div>
                          <div className="text-xs text-gray-500">{new Date(lead.recycledAt).toLocaleString()}</div>
                        </div>
                      ) : <span className="text-gray-400">-</span>}
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                      {new Date(lead.createdAt).toLocaleDateString()}
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* 弹窗：文件导入 */}
      {showImportModal && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white rounded-lg p-6 w-[400px] shadow-xl relative">
             <button 
              onClick={() => setShowImportModal(false)}
              className="absolute top-4 right-4 text-gray-400 hover:text-gray-600"
            >
              <X className="w-5 h-5" />
            </button>
            <h3 className="text-lg font-bold mb-1">导入线索</h3>
            <p className="text-sm text-gray-500 mb-6">请上传 Excel 或 CSV 文件进行线索导入</p>

            <div 
              className="border-2 border-dashed border-gray-300 rounded-lg p-8 text-center hover:bg-gray-50 cursor-pointer transition-colors"
              onClick={() => fileInputRef.current?.click()}
            >
               <input 
                type="file" 
                ref={fileInputRef}
                className="hidden" 
                accept=".xlsx,.xls,.csv"
                onChange={handleFileChange}
              />
              <UploadCloud className="w-10 h-10 text-gray-400 mx-auto mb-3" />
              {selectedFile ? (
                 <div className="text-sm text-indigo-600 font-medium">
                   {selectedFile.name}
                 </div>
              ) : (
                <div className="text-sm text-gray-500">
                  <span className="text-indigo-600 font-medium">点击上传</span> 或拖拽文件到此处
                </div>
              )}
              <p className="text-xs text-gray-400 mt-2">支持扩展名: .xlsx, .xls, .csv</p>
            </div>

            <div className="flex justify-end gap-3 mt-6">
              <button 
                onClick={() => setShowImportModal(false)}
                className="px-4 py-2 text-sm text-gray-700 hover:bg-gray-100 rounded-md"
              >
                取消
              </button>
              <button 
                onClick={handleExecuteImport}
                disabled={!selectedFile || loading}
                className="px-4 py-2 text-sm bg-indigo-600 text-white rounded-md hover:bg-indigo-700 disabled:opacity-50"
              >
                {loading ? '导入中...' : '开始导入'}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* 弹窗：选择员工 */}
      {showAssignModal && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white rounded-lg p-6 w-96 shadow-xl transform transition-all">
            <h3 className="text-lg font-bold mb-4">分配 {selectedLeadIds.size} 条线索</h3>
            <div className="mb-4">
              <label className="block text-sm font-medium text-gray-700 mb-1">选择员工</label>
              <select 
                value={assignTargetId}
                onChange={(e) => setAssignTargetId(e.target.value)}
                className="w-full border border-gray-300 rounded-md shadow-sm p-2 focus:ring-indigo-500 focus:border-indigo-500"
              >
                <option value="">-- 请选择 --</option>
                {employees.map(emp => (
                  <option key={emp.id} value={emp.id}>{emp.name} (当前线索: {emp.assignedLeadsCount})</option>
                ))}
              </select>
            </div>
            <div className="flex justify-end gap-3">
              <button 
                onClick={() => setShowAssignModal(false)}
                className="px-4 py-2 text-sm text-gray-700 hover:bg-gray-100 rounded-md"
              >
                取消
              </button>
              <button 
                onClick={handlePreAssign}
                className="px-4 py-2 text-sm bg-indigo-600 text-white rounded-md hover:bg-indigo-700"
              >
                下一步
              </button>
            </div>
          </div>
        </div>
      )}

      {/* 弹窗：二次确认 */}
      {showConfirmModal && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-[60]">
          <div className="bg-white rounded-lg p-6 w-96 shadow-xl transform transition-all border-t-4 border-indigo-500">
            <div className="flex items-center gap-3 text-gray-800 mb-4">
              <AlertTriangle className="w-6 h-6 text-indigo-500" />
              <h3 className="text-lg font-bold">请确认分配操作</h3>
            </div>

            <div className="bg-gray-50 p-4 rounded-md mb-6 text-sm text-gray-600">
              <p className="mb-2">您即将执行以下分配：</p>
              <ul className="space-y-1 list-disc list-inside">
                <li>线索数量：<strong className="text-gray-900">{selectedLeadIds.size}</strong> 条</li>
                <li>接收员工：<strong className="text-indigo-700 text-base">{targetEmployeeName}</strong></li>
              </ul>
            </div>

            <div className="flex justify-end gap-3">
              <button 
                onClick={() => {
                   setShowConfirmModal(false);
                   setShowAssignModal(true); // 返回上一步
                }}
                className="px-4 py-2 text-sm text-gray-600 hover:bg-gray-100 rounded-md"
              >
                返回修改
              </button>
              <button 
                onClick={handleExecuteAssign}
                disabled={loading}
                className="px-4 py-2 text-sm bg-indigo-600 text-white rounded-md hover:bg-indigo-700 disabled:opacity-50 shadow-sm"
              >
                {loading ? '处理中...' : '确认分配'}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useEffect, useState, useRef } from 'react';
