    try {
      await mockDeleteEmployee(emp.id);
      await fetchEmployees();
      alert('员工已删除');
    } catch(e) {
      alert('删除失败');
    } finally {
      setLoading(false);
    }
  };

  const handleSaveEmployee = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    try {
      if (editingEmployee.id) {
