import React, { useEffect, useState, useRef } from 'react';
import { Lead, Employee, LeadStatus, EmployeeStatus, Role, RecycleReason, FollowUp } from '../types';
import { 
  mockListLeads, 
  mockListEmployees, 
  mockAssignLeadsToEmployee, 
  mockAutoAssignLeads, 
  mockImportLeads,
  mockCreateLead,
  mockUpdateLeadInfo,
  mockDeleteLead,
  mockGetFollowUps
} from '../mock/api';
