  UploadCloud, 
  Filter, 
  RefreshCw, 
  X, 
  ChevronLeft, 
  ChevronRight, 
  CheckCircle, 
  AlertTriangle,
  Search,
  Plus,
  Trash2,
  Edit,
  Eye,
  Clock,
  Phone
} from 'lucide-react';

interface LeadPoolProps {
  currentUserRole: Role;
}

// User provided mock data for import simulation
const STATIC_IMPORT_DATA = [
  { "id": 1, "name": "张伟", "phone": "13800138001", "region": "北京" },
